import collections
import sys

def BFSS(graph, sv, n, col):
	q = collections.deque([sv])
	col[sv] = 1
	while q:
		v = q.popleft()
		for u in range(n):
			if col[u] == -1 and graph[u][v]:
				q.append(u)
				col[u] = 1 - col[v]
			elif graph[u][v] and col[v] == col[u]:
				return False
	return True

def BFS(graph, n):
	col = [-1] * n
	for i in range(n):
		if col[i] == -1:
			ans = BFSS(graph, i, n, col)
			if ans == False:
				print('NO')
				return
	print('YES')
